// Auto-generated per-language descriptions for de
// DO NOT EDIT - generated from descriptions.ts
export const descriptions_de: Record<string, Record<string, string>> = {
  "length": {
    "mm": "Das Millimeter (mm) ist die kleinste gebräuchliche metrische Längeneinheit und entspricht einem Tausendstel eines Meters. Es wird häufig in technischen Zeichnungen, Fertigungstoleranzen und Niederschlagsmessungen verwendet, wo Präzision wichtig ist. Ein Millimeter entspricht ungefähr 0,0394 Zoll, was es ideal macht, um dünne Materialien wie Papier oder Draht zu beschreiben.",
    "cm": "Der Zentimeter (cm) ist eine metrische Längeneinheit, die einem Hundertstel eines Meters entspricht und weltweit häufig für alltägliche Messungen verwendet wird. Er erscheint auf Linealen, bei Kleidergrößen und in medizinischen Unterlagen für Körpermessungen. Ein Zentimeter entspricht ungefähr 0,3937 Zoll und bietet eine praktische Skala zwischen Millimetern und Metern.",
    "m": "Der Meter (m) ist die Basiseinheit der Länge im Internationalen Einheitensystem, ursprünglich definiert durch die Entfernung, die Licht im Vakuum in 1/299.792.458 einer Sekunde zurücklegt. Er dient als Grundlage für alle metrischen Längenmessungen und wird weltweit im Bauwesen, im Sport und in der wissenschaftlichen Forschung verwendet. Ein Meter entspricht ungefähr 3,2808 Fuß oder etwa 1,0936 Yards.",
    "km": "Der Kilometer (km) entspricht 1.000 Metern und ist die standardmäßige Einheit zur Messung langer Distanzen zwischen Städten, Ländern und geografischen Merkmalen. Verkehrsschilder in den meisten Ländern zeigen Entfernungen in Kilometern an, und Laufwettbewerbe verwenden häufig Kilometer-Markierungen. Ein Kilometer ist ungefähr 0,6214 Meilen, was die Umrechnung zwischen metrischen und imperialen Entfernungsskalen erleichtert.",
    "inch": "Der Zoll (in) ist eine imperiale Längeneinheit, die genau 25,4 Millimeter beträgt und weit verbreitet in den Vereinigten Staaten, Kanada und dem Vereinigten Königreich verwendet wird. Er ist die Standardmessung für Bildschirmgrößen, Rohrdurchmesser und mechanische Befestigungen und bleibt im Alltag in Nordamerika üblich. Ein Zoll entspricht genau 2,54 Zentimetern.",
    "foot": "Der Fuß (ft) ist eine imperiale Maßeinheit, die 12 Zoll oder 0,3048 Meter entspricht und fest in der amerikanischen Bauwirtschaft, den Flughöhen und alltäglichen Messungen verankert ist. Im Immobilienbereich werden Raumgrößen und Grundstücksflächen in den gesamten Vereinigten Staaten fast immer in Fuß angegeben. Ein Fuß entspricht genau 30,48 Zentimetern.",
    "yard": "Der Yard (yd) ist eine imperiale Einheit, die 3 Fuß oder 0,9144 Meter entspricht und in den Vereinigten Staaten häufig zum Messen von Stoff, Fußballfeldern und mittellangen Entfernungen verwendet wird. Er bietet einen praktischen Mittelweg zwischen Fuß und Meilen für Messungen im Freien. Ein Yard entspricht genau 0,9144 Metern, was für schnelle Schätzungen nahe genug an einem Meter liegt.",
    "mile": "Die Meile (mi) ist eine imperiale Längeneinheit, die 5.280 Fuß bzw. ungefähr 1,6093 Kilometer entspricht und hauptsächlich in den Vereinigten Staaten und im Vereinigten Königreich für Straßenentfernungen verwendet wird. Geschwindigkeitsbegrenzungen auf amerikanischen Autobahnen werden in Meilen pro Stunde angegeben, und Läufer verwenden die Meile oft als Referenzdistanz. Eine Meile entspricht ungefähr 1,609 Kilometern."
  },
  "weight": {
    "mg": "Das Milligramm (mg) ist eine winzige metrische Masseeinheit, die einem Tausendstel Gramm entspricht und in der Pharmazie und bei Nährwertangaben unverzichtbar ist. Medikamentendosierungen, Vitaminmengen und Mengen von Zusatzstoffen in Lebensmitteln werden typischerweise in Milligramm angegeben. Ein Milligramm entspricht ungefähr 0,0000353 Unzen, was es zur bevorzugten Einheit für die Messung äußerst kleiner Massen macht.",
    "g": "Das Gramm (g) ist die Basiseinheit der Masse im metrischen System und wird als ein Tausendstel eines Kilogramms definiert. Es ist die Standardmessung für Lebensmittelportionen, Postgebühren und kleine Gegenstände im täglichen Leben in den meisten Teilen der Welt. Ein Gramm entspricht ungefähr 0,0353 Unzen, und eine Standard-Heftklammer wiegt ungefähr ein Gramm.",
    "kg": "Das Kilogramm (kg) ist die Basiseinheit der Masse im Internationalen Einheitensystem und seit 2019 durch das Plancksche Wirkungsquantum definiert. Es ist die weltweit am häufigsten verwendete Masseeinheit für Körpergewicht, Lebensmittelartikel und Versand und erscheint auf Waagen in Haushalten und Märkten überall. Ein Kilogramm entspricht ungefähr 2,2046 Pfund.",
    "tonne": "Die metrische Tonne oder Tonne (t) entspricht 1.000 Kilogramm und wird weltweit zur Messung von schwerer Fracht, industrieller Produktion und Fahrzeuggewichten verwendet. Versandcontainer, Stahlproduktion und Treibhausgasemissionen werden alle häufig in Tonnen angegeben. Eine Tonne entspricht ungefähr 2.204,6 Pfund oder etwa 1,1023 US-Tonnen.",
    "oz": "Die Unze (oz) ist eine imperiale Gewichtseinheit, die ungefähr 28,35 Gramm entspricht und in den Vereinigten Staaten weit verbreitet für Lebensmittelverpackungen, Postdienste und Edelmetalle verwendet wird. In der Küche geben Rezepte oft Zutaten in Unzen an, und Gold und Silber werden in Feinunzen gehandelt. Eine Unze entspricht ungefähr 28,35 Gramm.",
    "lb": "Das Pfund (lb) ist eine imperiale Masseeinheit, die genau 0,45359237 Kilogramm entspricht und als primäre Gewichtseinheit in den Vereinigten Staaten und Teilen des Britischen Commonwealth dient. Körpergewicht, Fitnessgeräte und verpackte Waren in Amerika werden fast immer in Pfund angegeben. Ein Pfund entspricht 16 Unzen oder ungefähr 0,4536 Kilogramm.",
    "st": "Der Stein (st) ist eine britische imperiale Einheit, die 14 Pfund oder etwa 6,35 Kilogramm entspricht und traditionell im Vereinigten Königreich und Irland für das Körpergewicht verwendet wird. Wenn jemand im Vereinigten Königreich sagt, dass er 11 Stein wiegt, meint er 154 Pfund, eine Konvention, die im alltäglichen Gespräch und in medizinischen Aufzeichnungen bestehen bleibt. Ein Stein entspricht genau 6,35029 Kilogramm.",
    "jin": "Der Jin (斤) ist eine traditionelle chinesische Gewichtseinheit, die 500 Gramm entspricht, also genau einem halben Kilogramm. Er bleibt die gebräuchlichste Gewichtseinheit auf chinesischen Märkten, in Lebensmittelgeschäften und im täglichen Leben, wo Gemüse, Fleisch und Obst nach Jin verkauft werden. Ein Jin entspricht 1,1023 Pfund oder genau 500 Gramm."
  },
  "temperature": {
    "c": "Celsius (°C) ist die weltweit am weitesten verbreitete Temperaturskala, wobei 0°C den Gefrierpunkt von Wasser und 100°C dessen Siedepunkt bei normalem atmosphärischem Druck markieren. Sie dient als Standardtemperatur in fast allen Ländern außer den Vereinigten Staaten und erscheint in Wettervorhersagen, Kochanleitungen und wissenschaftlicher Literatur. Um Celsius in Fahrenheit umzurechnen, multipliziert man mit 9/5 und addiert 32.",
    "f": "Fahrenheit (°F) ist eine Temperaturskala, bei der 32°F den Gefrierpunkt von Wasser und 212°F seinen Siedepunkt markieren, hauptsächlich in den Vereinigten Staaten für Wetter, Kochen und alltägliche Temperaturangaben verwendet. Sie bietet eine feinere Granularität als Celsius, wobei jedes Grad eine geringere Temperaturänderung darstellt. Um Fahrenheit in Celsius umzurechnen, zieht man 32 ab und multipliziert mit 5/9.",
    "k": "Kelvin (K) ist die Basiseinheit der thermodynamischen Temperatur im Internationalen Einheitensystem, wobei 0 K den absoluten Nullpunkt darstellt, den theoretischen Punkt null thermischer Energie. Wissenschaftler verwenden Kelvin in der Physik, Chemie und Astronomie, weil es bei null beginnt und keine negativen Werte hat, was Berechnungen vereinfacht. Null Grad Celsius entsprechen 273,15 Kelvin, und die beiden Skalen teilen sich die gleiche Größe der Gradeinheiten."
  },
  "data": {
    "bit": "Das Bit ist die grundlegendste Einheit digitaler Informationen und repräsentiert einen einzelnen binären Wert von entweder 0 oder 1. Jedes gespeicherte oder über das Internet übertragene Datenstück besteht letztlich aus Bits, von einem einzelnen Textzeichen bis hin zu hochauflösenden Videostreams. Acht Bits ergeben ein Byte, weshalb die Datenspeicherung typischerweise in Bytes und nicht in Bits diskutiert wird.",
    "b": "Das Byte (B) ist die Standardmaßeinheit der digitalen Speicherung und besteht aus 8 Bits, genug, um ein einzelnes Zeichen wie einen Buchstaben oder eine Zahl darzustellen. Dateigrößen, Speicherkapazität und Speichergeräte werden alle in Bytes oder deren Vielfachen gemessen, wodurch es die am häufigsten referenzierte Einheit in der Computertechnik ist. Ein Byte entspricht genau 8 Bits und kann 256 verschiedene Werte darstellen.",
    "kb": "Das Kilobyte (KB) entspricht 1.024 Bytes in binären Computerbegriffen und wird verwendet, um kleine Dateien wie Textdokumente, E-Mail-Nachrichten und Miniaturbilder zu messen. Während der Begriff in Netzwerkzusammenhängen manchmal 1.000 Bytes bezeichnet, verwenden Betriebssysteme konsequent die binäre Definition. Ein Kilobyte kann ungefähr eine halbe Seite Klartext speichern.",
    "mb": "Das Megabyte (MB) entspricht 1.024 Kilobytes oder 1.048.576 Bytes und wird üblicherweise verwendet, um die Größe von Fotos, Musikdateien und Anwendungen zu beschreiben. Ein typisches Smartphone-Foto liegt zwischen 2 und 10 MB, und ein einzelnes Lied im MP3-Format hat ungefähr 3 bis 5 MB. Es bleibt eine der am häufigsten angetroffenen Einheiten bei der Verwaltung persönlicher digitaler Speicher.",
    "gb": "Das Gigabyte (GB) entspricht 1.024 Megabyte oder ungefähr 1,07 Milliarden Bytes und stellt die Standardmessung für die Speicherkapazität von Handys, Laptops und USB-Laufwerken dar. Ein typischer HD-Film benötigt 2 bis 4 GB Speicherplatz, und die meisten mobilen Datentarife werden in Gigabyte pro Monat gemessen. Es überbrückt die Lücke zwischen alltäglichen Dateigrößen und großflächiger Datenspeicherung.",
    "tb": "Das Terabyte (TB) entspricht 1.024 Gigabyte oder ungefähr 1,1 Billionen Bytes und wird für großflächige Speicherung wie Festplatten, Cloud-Backups und Unternehmensdatenbanken verwendet. Moderne externe Festplatten bieten üblicherweise 1 bis 8 TB Speicherplatz, genug, um Hunderttausende von Fotos oder Tausende von Stunden Video zu speichern. Ein Terabyte stellt nach den alltäglichen Maßstäben von Verbrauchern eine enorme Datenmenge dar.",
    "pb": "Das Petabyte (PB) entspricht 1.024 Terabyte oder ungefähr 1,13 Billiarden Bytes und repräsentiert Speichervolumen, die von großen Technologieunternehmen, Forschungseinrichtungen und Cloud-Plattformen genutzt werden. Große Streaming-Dienste, soziale Netzwerke und wissenschaftliche Datensätze werden in Petabytes gemessen, aufgrund des gewaltigen Volumens an nutzergenerierten Inhalten. Ein Petabyte kann ungefähr 500 Milliarden Seiten Standardtext speichern.",
    "kbit": "Das Kilobit (Kbit) entspricht 1.000 Bits und wird hauptsächlich verwendet, um Datenübertragungsraten in Netzwerken zu messen, wie zum Beispiel Internetgeschwindigkeiten. Internetdienstanbieter werben häufig mit Geschwindigkeiten in Kilobit pro Sekunde (Kbps) oder Megabit pro Sekunde, wodurch Kilobits eine wichtige Einheit zum Verständnis der Bandbreite darstellen. Ein Kilobit entspricht 125 Bytes und unterscheidet sich damit deutlich vom Kilobyte.",
    "mbit": "Das Megabit (Mbit) entspricht 1.000 Kilobits oder einer Million Bits, am häufigsten zu sehen bei Internetgeschwindigkeitsangaben, bei denen Internetanbieter Pläne in Megabit pro Sekunde (Mbps) bewerben. Es ist wichtig, Megabits von Megabytes zu unterscheiden, da eine 100-Mbps-Verbindung ungefähr 12,5 Megabytes pro Sekunde tatsächliche Downloadgeschwindigkeit liefert. Diese Einheit ist entscheidend für den Vergleich und das Verständnis der Netzwerkleistung.",
    "gbit": "Das Gigabit (Gbit) entspricht 1.000 Megabit oder einer Milliarde Bits und wird verwendet, um Hochgeschwindigkeitsnetzwerkverbindungen und Rechenzentrumsanbindungen zu beschreiben. Moderne Glasfaser-Internetpläne erreichen oft Gigabit-Geschwindigkeiten, und Unternehmensnetzwerke sind auf Durchsatz auf Gigabit-Niveau angewiesen, um große Datenmengen zu bewältigen. Ein Gigabit entspricht 125 Megabyte, was den praktischen Unterschied zwischen Bits und Bytes verdeutlicht."
  },
  "area": {
    "sqmm": "Der Quadratmillimeter (mm²) ist eine metrische Flächeneinheit, die einem Millionstel eines Quadratmeters entspricht und in der Präzisionsingenieurtechnik, der Mikroelektronik und der medizinischen Bildgebung verwendet wird. Er ist ideal zur Messung des Querschnitts von Drähten, der Oberfläche von Mikrochips und anderen winzigen Flächen. Ein Quadratmillimeter entspricht ungefähr 0,00155 Quadratzoll.",
    "sqcm": "Der Quadratzentimeter (cm²) ist eine metrische Flächeneinheit, die einem Zehntausendstel eines Quadratmeters entspricht und häufig in medizinischen Berichten, Labormaßen und kleinen Produktspezifikationen verwendet wird. Hautläsionsgrößen, Stoffmuster und Leiterplattenkomponenten werden oft in Quadratzentimetern gemessen. Ein Quadratzentimeter entspricht genau 0,155 Quadratzoll.",
    "sqm": "Der Quadratmeter (m²) ist die SI-Basiseinheit der Fläche, gleich einem Quadrat mit einer Länge von einem Meter auf jeder Seite, und wird weltweit für Immobilien, Bauwesen und Landvermessung verwendet. Wohnungsgrößen, Bürogrundrisse und Baukosten werden außerhalb der Vereinigten Staaten fast ausschließlich in Quadratmetern angegeben. Ein Quadratmeter entspricht ungefähr 10,764 Quadratfuß.",
    "sqkm": "Der Quadratkilometer (km²) entspricht einer Million Quadratmetern und wird verwendet, um große Landflächen wie Städte, Nationalparks und Länder zu messen. Geografische Daten, Berichte zur Stadtplanung und ökologische Studien verwenden Quadratkilometer als ihre standardmäßige Flächeneinheit. Ein Quadratkilometer entspricht ungefähr 0,3861 Quadratmeilen oder etwa 247,1 Acres.",
    "ha": "Der Hektar (ha) ist eine metrische Flächeneinheit, die 10.000 Quadratmetern oder 100 Ar entspricht und weltweit in der Landwirtschaft, Forstwirtschaft und im Landmanagement weit verbreitet ist. Höfe, Weinberge und Naturschutzgebiete werden typischerweise in Hektar in Europa, Asien und Ozeanien beschrieben. Ein Hektar entspricht ungefähr 2,471 Acres und bietet eine praktische Verbindung zwischen metrischen und imperialen Flächenmaßen.",
    "acre": "Der Acre ist eine imperiale Flächeneinheit, die 43.560 Quadratfuß oder etwa 4.047 Quadratmeter entspricht und hauptsächlich in den Vereinigten Staaten, Großbritannien und ehemaligen britischen Kolonien zur Landmessung verwendet wird. Immobilienanzeigen, Grenzen von Ackerland und Vorstadtgrundstücke in diesen Regionen werden üblicherweise in Acres angegeben. Ein Acre entspricht ungefähr 90 % eines Standard-Fußballfeldes.",
    "sqft": "Der Quadratfuß (ft²) ist eine imperiale Flächeneinheit, die einem Quadrat entspricht, das auf jeder Seite einen Fuß misst, die Standardmessung für Hausgrößen, Büroflächen und Mietobjekte in den Vereinigten Staaten. Immobilienanzeigen in Amerika geben fast immer die Wohnfläche in Quadratfuß an, was es zu einer der praktisch relevantesten Flächeneinheiten macht. Ein Quadratfuß entspricht genau 0,0929 Quadratmetern.",
    "sqin": "Der Quadratzoll (in²) ist eine kleine imperiale Flächeneinheit, die einem Quadrat mit einer Seitenlänge von einem Zoll entspricht. Sie wird häufig in technischen Spezifikationen, Bildschirmgrößenbeschreibungen und Druckmessungen verwendet. Kolbenflächen, Materialspannungsberechnungen und Größen elektronischer Bauteile werden häufig in Quadratzoll angegeben. Ein Quadratzoll entspricht genau 6,4516 Quadratzentimetern.",
    "sqmi": "Der Quadratmeile (mi²) ist eine große imperiale Flächeneinheit, die 640 Acres oder etwa 2,59 Quadratkilometern entspricht und zur Messung großer Gebiete wie Städten, Landkreisen und Nationalparks verwendet wird. Geografische Daten in den Vereinigten Staaten und im Vereinigten Königreich beziehen sich häufig auf Quadratmeilen beim Beschreiben von Regionen, insbesondere bei Berechnungen der Bevölkerungsdichte. Eine Quadratmeile entspricht genau 2,58999 Quadratkilometern.",
    "mu": "Der Mu (亩) ist eine traditionelle chinesische Flächeneinheit, die ungefähr 666,67 Quadratmetern entspricht und in der chinesischen Landwirtschaft, bei ländlichen Landverträgen und in Immobilienunterlagen weit verbreitet verwendet wird. Ackerland in China wird fast immer in Mu gemessen, und staatliche Richtlinien bezüglich Getreideproduktionsquoten beziehen sich auf diese Einheit. Ein Mu entspricht etwa 0,1647 Acres oder etwa 7.176 Quadratfuß."
  },
  "volume": {
    "ml": "Das Milliliter (mL) ist eine metrische Volumeneinheit, die einem Tausendstel Liter entspricht und wird häufig in der Medizin, beim Kochen und in der Chemie zur Messung kleiner Flüssigkeitsmengen verwendet. Dosierungen von Hustensaft, Parfümfläschchen und Laborreagenzien sind alle üblicherweise in Millilitern gekennzeichnet. Ein Milliliter entspricht genau einem Kubikzentimeter, wodurch er in wissenschaftlichen Kontexten mit cm³ austauschbar ist.",
    "cl": "Der Zentiliter (cL) ist eine metrische Volumeneinheit, die einem Hundertstel Liter entspricht und in europäischen Ländern häufig für Größen von Getränke- und Spirituosenflaschen verwendet wird. Wein- und Spirituosenschilder in der EU zeigen oft das Volumen in Zentilitern zusammen mit Millilitern an. Ein Zentiliter entspricht genau 10 Millilitern oder etwa 0,338 Flüssigunzen.",
    "dl": "Das Deziliter (dL) ist eine metrische Volumeneinheit, die einem Zehntel Liter entspricht und in medizinischen Laborberichten sowie in einigen europäischen Rezepten verwendet wird. Bluttestergebnisse in vielen Ländern geben Cholesterin- und Glukosespiegel in Milligramm pro Deziliter an, wodurch diese Einheit jedem, der Gesundheitsdaten überprüft, vertraut ist. Ein Deziliter entspricht genau 100 Millilitern oder ungefähr 3,381 Flüssigunzen.",
    "l": "Der Liter (L) ist die am weitesten verbreitete metrische Einheit für Volumen, gleich 1.000 Kubikzentimetern oder einem Kubikdezimeter, und dient weltweit als Standard für Getränke, Kraftstoff und Haushaltsflüssigkeiten. Benzinpreise, Flaschenwasser und Milchpackungen beziehen sich in den meisten Ländern auf Liter. Ein Liter entspricht ungefähr 1,0567 US-Quarts oder 0,2642 US-Gallonen.",
    "m3": "Der Kubikmeter (m³) ist die SI-Basiseinheit für Volumen und stellt den Raum dar, der von einem Würfel mit einer Kantenlänge von einem Meter eingenommen wird. Er wird im Bauwesen, Versand und bei industriellen Prozessen verwendet. Wasserrechnungen, Betonbestellungen und Frachtberechnungen basieren alle auf Kubikmetern als Standardmaß. Ein Kubikmeter entspricht genau 1.000 Litern oder etwa 264,2 US-Gallonen.",
    "gal": "Der US-Gallone (gal) ist eine imperiale Volumeneinheit, die genau 3,7854 Liter entspricht und die Standardmessung für Kraftstoff, Milch und Farbe in den Vereinigten Staaten darstellt. Die Benzinpreise an amerikanischen Tankstellen werden immer pro Gallone angegeben, und die Kraftstoffeffizienz von US-Fahrzeugen wird in Meilen pro Gallone gemessen. Eine US-Gallone entspricht 4 US-Quart oder 8 US-Pints.",
    "gal_uk": "Der britische Gallone (imperiale Gallone) entspricht genau 4,54609 Litern, etwa 20 % mehr als die US-Gallone, und bleibt die Standardkraftstoffmessung im Vereinigten Königreich und einigen Commonwealth-Ländern. Die britische Kraftstoffeffizienz wird in Meilen pro imperialer Gallone angegeben, was höhere Zahlen als die US-amerikanische Entsprechung ergibt. Eine britische Gallone entspricht etwa 1,201 US-Gallonen.",
    "qt": "Das US-Quart (qt) ist eine imperiale Volumeneinheit, die einem Viertel eines US-Gallons oder genau 0,9464 Litern entspricht und häufig in der amerikanischen Küche und bei Lebensmittelverpackungen verwendet wird. Motorölbehälter und Eisschalen in den Vereinigten Staaten verwenden häufig Quart-Maße. Ein US-Quart entspricht genau 2 US-Pints oder ungefähr 32 US-Flüssigunzen.",
    "pt": "Die US-Pinte (pt) ist eine imperialistische Volumeneinheit, die einem Achtel einer US-Gallone oder ungefähr 0,4732 Litern entspricht und am besten für Biergläser und Eisschalen in Amerika bekannt ist. Der Ausdruck 'a pint is a pound the world around' erfasst ihre umgangssprachliche Bedeutung, obwohl eine Pinte Wasser tatsächlich etwa 1,043 Pfund wiegt. Eine US-Pinte entspricht genau 16 US-Flüssigunzen.",
    "cup": "Die US-Tasse ist eine Volumeneinheit, die 8 US-Flüssigunzen oder etwa 0,2366 Liter entspricht und die Standardmessung in amerikanischen Rezepten und Kochbüchern ist. Wenn ein Rezept nach „einer Tasse Mehl“ oder „einer halben Tasse Zucker“ verlangt, bezieht es sich auf dieses spezifische Volumen und nicht auf ein Trinkgefäß beliebiger Größe. Eine US-Tasse entspricht genau 236,588 Millilitern.",
    "floz": "Die US-Flüssigkeitsunze (fl oz) ist eine Volumeneinheit, die ungefähr 29,574 Milliliter entspricht und zur Kennzeichnung von Getränken, Kosmetika und Körperpflegeprodukten in den Vereinigten Staaten verwendet wird. Getränkedosen, Shampooflaschen und Hautpflege-Seren geben alle ihren Inhalt in Flüssigkeitsunzen für amerikanische Verbraucher an. Eine Flüssigkeitsunze entspricht genau 1/128 US-Gallone oder ungefähr 2 Esslöffeln.",
    "tbsp": "Der Esslöffel (EL) ist eine Volumeneinheit, die 3 Teelöffeln oder ungefähr 14,787 Millilitern entspricht und hauptsächlich in Kochrezepten und Nährwertangaben verwendet wird. In der Küche liefert ein Esslöffel Butter, Öl oder Zucker eine gleichbleibende Menge, unabhängig von der physischen Größe des Löffels. Ein US-Esslöffel entspricht genau 0,5 US-Flüssigunzen.",
    "tsp": "Der Teelöffel (TL) ist die kleinste standardisierte Maßeinheit für Kochvolumen, ungefähr 4,929 Milliliter, die in Rezepten weltweit zur Messung kleiner Mengen von Gewürzen, Extrakten und Medikamenten verwendet wird. Er dient als Baustein für größere Messungen, wobei drei Teelöffel einen Esslöffel ergeben. Ein US-Teelöffel entspricht genau 1/6 einer US-Flüssigunze."
  },
  "speed": {
    "ms": "Meter pro Sekunde (m/s) ist die SI-Basiseinheit für Geschwindigkeit und Geschwindigkeit, die die in Metern zurückgelegte Strecke während einer Sekunde darstellt. Es ist die Standardeinheit in Physik, Ingenieurwesen und wissenschaftlicher Forschung, die verwendet wird, um alles von fallenden Objekten bis zu Strömungsgeschwindigkeiten zu beschreiben. Ein Meter pro Sekunde entspricht genau 3,6 Kilometern pro Stunde oder ungefähr 2,237 Meilen pro Stunde.",
    "kmh": "Kilometer pro Stunde (km/h) ist die am häufigsten verwendete Geschwindigkeitseinheit außerhalb der Vereinigten Staaten und wird auf Tachometern und Verkehrsschildern in ganz Europa, Asien und den meisten Teilen der Welt angezeigt. Autobahn-Geschwindigkeitsbegrenzungen, Wetterberichte über Windgeschwindigkeiten und Fahrzeugleistungsangaben in diesen Regionen verwenden alle km/h. Ein Kilometer pro Stunde entspricht ungefähr 0,2778 Meter pro Sekunde oder etwa 0,6214 Meilen pro Stunde.",
    "mph": "Meilen pro Stunde (mph) ist die Standardgeschwindigkeitseinheit in den Vereinigten Staaten, dem Vereinigten Königreich und einigen anderen Ländern, die für Geschwindigkeitsbegrenzungen, Fahrzeugtachometer und Wettervorhersagen verwendet wird. Amerikanische Verkehrsschilder zeigen ausschließlich Geschwindigkeitsbegrenzungen in mph an, und Autoenthusiasten beziehen sich häufig auf 0-60-mph-Zeiten als Leistungsmaßstab. Eine Meile pro Stunde entspricht genau 1,60934 Kilometern pro Stunde.",
    "kn": "Der Knoten (kn) entspricht einer nautischen Meile pro Stunde oder etwa 1,852 Kilometern pro Stunde, der universellen Geschwindigkeitseinheit für die Schifffahrts- und Luftfahrtnavigation. Schiffsgeschwindigkeiten, Flugzeuggeschwindigkeiten und Windgeschwindigkeiten in meteorologischen Berichten verwenden alle Knoten als Standardmaß. Ein Knoten entspricht genau 1,15078 Meilen pro Stunde, was die längere nautische Meile im Vergleich zur Landmeile widerspiegelt.",
    "fts": "Fuß pro Sekunde (ft/s) ist eine imperiale Geschwindigkeitseinheit, die in den USA häufig in der Ballistik, Fluiddynamik und Ingenieurrechnung verwendet wird. Projektilgeschwindigkeiten, Rohrströmungsraten und Förderbandgeschwindigkeiten werden in amerikanischen technischen Dokumentationen oft in ft/s angegeben. Ein Fuß pro Sekunde entspricht genau 0,3048 Metern pro Sekunde oder etwa 0,6818 Meilen pro Stunde.",
    "mach": "Mach (Ma) ist eine dimensionslose Geschwindigkeitseinheit, die das Verhältnis der Geschwindigkeit eines Objekts zur Schallgeschwindigkeit im umgebenden Medium angibt. Auf Meereshöhe unter Standardbedingungen entspricht Mach 1 ungefähr 343 Metern pro Sekunde oder 1.235 Kilometern pro Stunde, obwohl dies mit Höhe und Temperatur variiert. Überschallflugzeuge fliegen über Mach 1, während Hyperschallfahrzeuge Mach 5 überschreiten."
  },
  "time": {
    "ms_time": "Die Millisekunde (ms) ist eine Zeiteinheit, die einem Tausendstel einer Sekunde entspricht und in der Informatik, Telekommunikation und wissenschaftlichen Experimenten, bei denen präzises Timing wichtig ist, von entscheidender Bedeutung ist. Netzwerkverzögerungen, Kameraverschlusszeiten und Reaktionszeitmessungen arbeiten alle auf der Millisekunden-Skala. Eine Millisekunde entspricht genau 0,001 Sekunden, und das menschliche Auge kann Veränderungen, die schneller als etwa 10 Millisekunden auftreten, kaum wahrnehmen.",
    "s": "Die Sekunde (s) ist die Basiseinheit der Zeit im Internationalen Einheitensystem, definiert durch die Schwingungsfrequenz von Cäsium-133-Atomen. Sie dient als Grundlage für alle Zeitmessungen, von Uhren und Armbanduhren bis hin zu GPS-Satelliten und Atomphysik. Eine Sekunde entspricht genau 1.000 Millisekunden und ist in 60 Sekunden pro Minute unterteilt.",
    "min": "Die Minute (min) ist eine Zeiteinheit, die 60 Sekunden entspricht und universell für Zeitplanung, Küchentimer und die tägliche Zeitmessung verwendet wird. Dauer von Besprechungen, Trainingsintervalle und Fahrpläne basieren alle auf Minuten als ihrer Haupteinheit. Eine Minute entspricht genau 60 Sekunden, und 60 Minuten ergeben eine Stunde.",
    "h": "Die Stunde (h) ist eine Zeiteinheit, die 60 Minuten oder 3.600 Sekunden entspricht und das Standardmaß für Arbeitsschichten, Reisezeiten und Geschäftszeiten weltweit darstellt. Lohnabrechnungen, Flugdauern und Tagespläne sind alle nach Stunden strukturiert. Eine Stunde entspricht genau 3.600 Sekunden, und 24 Stunden ergeben einen Tag.",
    "d": "Der Tag (d) ist eine Zeiteinheit, die 24 Stunden oder 86.400 Sekunden entspricht und eine vollständige Drehung der Erde um ihre Achse darstellt. Er ist der grundlegende Zyklus für menschliche Aktivitäten und organisiert Arbeitspläne, Schlafrhythmen und Kalendersysteme in jeder Kultur. Ein Tag entspricht genau 86.400 Sekunden oder 1.440 Minuten.",
    "wk": "Die Woche (wk) ist eine Zeiteinheit, die 7 Tagen oder 168 Stunden entspricht und als standardmäßiger Organisationszeitraum für Geschäftszyklen, Stundenpläne in Schulen und Abrechnungszeiträume in den meisten Kulturen dient. Projektzeitpläne, Fitnesspläne und wiederkehrende Ereignisse werden typischerweise wöchentlich geplant. Eine Woche entspricht genau 7 Tagen oder 604.800 Sekunden.",
    "mo": "Der Monat (Mo) ist eine Zeiteinheit, die im Durchschnitt etwa 30,44 Tage oder 2.629.746 Sekunden umfasst und für Abrechnungszyklen, Mietverträge und Finanzplanung verwendet wird. Kalendermonate variieren zwischen 28 und 31 Tagen, aber der Durchschnittsmonat bietet eine konsistente Referenz für langfristige Berechnungen. Ein durchschnittlicher Monat entspricht ungefähr 4,345 Wochen oder etwa 730,5 Stunden.",
    "yr": "Das Jahr (Jahr) ist eine Zeiteinheit, die ungefähr 365,25 Tagen oder 31.557.600 Sekunden entspricht und eine vollständige Umlaufbahn der Erde um die Sonne darstellt. Es ist die primäre Einheit für Alter, Finanzberichterstattung, Zinssätze und langfristige Verträge, wobei der viertägige Überschuss durch Schaltjahre ausgeglichen wird. Ein Jahr entspricht ungefähr 52,18 Wochen oder etwa 8.766 Stunden."
  },
  "pressure": {
    "pa": "Das Pascal (Pa) ist die SI-Basiseinheit des Drucks, definiert als ein Newton pro Quadratmeter, verwendet in Physik, Ingenieurwesen und Materialwissenschaft. Während es der wissenschaftliche Standard ist, werden alltägliche Drücke häufiger in Kilopascal oder Megapascal angegeben, da ein Pascal einen äußerst geringen Druck darstellt. Ein Pascal entspricht 0,00001 bar oder etwa 0,000145 psi.",
    "kpa": "Das Kilopascal (kPa) entspricht 1.000 Pascal und ist die praktischste Einheit für alltägliche Druckmessungen in metrischen Ländern. Reifendruck, Gebäudespezifikationen und Wetterberichte in Kanada, Australien und Europa verwenden häufig Kilopascal. Ein Kilopascal entspricht 0,01 Bar oder ungefähr 0,145 psi, was es zu einem praktischen Mittelweg zwischen wissenschaftlichen und industriellen Skalen macht.",
    "mpa": "Der Megapascal (MPa) entspricht einer Million Pascal und ist die Standard-Einheit für Hochdruckanwendungen im Bauwesen, in der Materialprüfung und in Hydrauliksystemen. Die Festigkeit von Beton wird in Megapascal angegeben, und Angaben zur Zugfestigkeit von Stahl beziehen sich routinemäßig auf diese Einheit. Ein Megapascal entspricht 10 Bar oder etwa 145 psi und überbrückt damit die metrischen und imperialen Druckskalen.",
    "bar": "Das Bar ist eine metrische Druckeinheit, die 100.000 Pascal entspricht und in der Meteorologie, Ozeanografie und in der Industrie weit verbreitet ist, da es dem atmosphärischen Druck auf Meereshöhe nahekommt. Reifendruckmesser in Europa, Tauchbereichsangaben beim Tauchen und Wetterkarten beziehen sich alle häufig auf Bar oder Millibar. Ein Bar entspricht ungefähr 0,9869 Atmosphären oder 14,504 psi.",
    "atm": "Die Standardatmosphäre (atm) ist eine Druckeinheit, die genau 101.325 Pascal definiert und den durchschnittlichen atmosphärischen Druck auf Meereshöhe auf der Erde darstellt. Sie dient als Bezugspunkt in der Chemie für Berechnungen von Gasgesetzen und in der Technik zur Bewertung von Druckgefäßkapazitäten. Eine Atmosphäre entspricht ungefähr 1,01325 bar, 14,696 psi oder 760 mmHg.",
    "psi": "PSI (Pfund pro Quadratzoll) ist eine imperiale Druckeinheit, die etwa 6.894,76 Pascal entspricht, der Standardmessung für Reifendruck, Druckluftsysteme und Hydraulikgeräte in den Vereinigten Staaten. Fast jede amerikanische Tankstellen-Luftpumpe und jeder Hochdruckreiniger zeigt Bewertungen in PSI an, was sie zu einer der weltweit bekanntesten Druckeinheiten macht. Ein PSI entspricht ungefähr 0,06895 bar oder 6,895 kPa.",
    "mmhg": "Das Millimeter Quecksilbersäule (mmHg) ist eine Druckeinheit, die etwa 133,322 Pascal entspricht und traditionell in der Medizin zur Messung des Blutdrucks sowie in der Meteorologie für barometrische Messungen verwendet wird. Ein normaler Blutdruck bei Erwachsenen von 120/80 mmHg wird von medizinischem Fachpersonal weltweit verstanden, wodurch diese Einheit in klinischen Einrichtungen unverzichtbar ist. Ein mmHg entspricht etwa 0,01934 psi oder 0,1333 kPa.",
    "torr": "Der Torr ist eine Druckeinheit, die nach Evangelista Torricelli benannt ist, ungefähr 133,322 Pascal entspricht und hauptsächlich in der Vakuumphysik und der Höhenforschung verwendet wird. Er ist nahezu identisch mit dem Millimeter Quecksilbersäule, wobei ein Torr genau als 1/760 einer Standardatmosphäre definiert ist. Vakuumpumpen, Elektronenmikroskope und Geräte zur Halbleiterherstellung geben häufig Betriebsdrücke in Torr an."
  },
  "energy": {
    "j": "Das Joule (J) ist die SI-Basiseinheit der Energie und wird als die Arbeit definiert, die verrichtet wird, wenn eine Kraft von einem Newton einen Gegenstand einen Meter bewegt. Es ist die universelle Einheit in der Physik zur Messung von kinetischer Energie, Wärme und elektrischer Energie und taucht in allem von Lehrbuchaufgaben bis hin zur Ernährungswissenschaft auf. Ein Joule entspricht der Energie, die freigesetzt wird, wenn ein kleiner Apfel einen Meter fallen gelassen wird, was es trotz seiner geringen Größe greifbar macht.",
    "kj": "Das Kilojoule (kJ) entspricht 1.000 Joule und ist die standardmäßige Einheit zur Angabe des Energiegehalts von Lebensmitteln und der Energien chemischer Reaktionen in Ländern, die das metrische System verwenden. Lebensmitteletiketten in Australien, Europa und vielen anderen Regionen zeigen die Energiewerte in Kilojoule entweder zusätzlich oder anstelle von Kalorien an. Ein Kilojoule entspricht ungefähr 238,8 Kalorien oder etwa 0,239 Kilokalorien.",
    "cal": "Die Kalorie (cal) ist eine kleine Energieeinheit, definiert als die Wärmemenge, die benötigt wird, um ein Gramm Wasser um ein Grad Celsius zu erwärmen, hauptsächlich verwendet in Physik und Chemie. Im alltäglichen Sprachgebrauch bezieht sich 'Kalorie' normalerweise auf die Kilokalorie (kcal), aber die wahre Kalorie ist 1/1.000 dieser Menge. Eine Kalorie entspricht genau 4,184 Joule und stellt eine direkte Verbindung zwischen thermischer und mechanischer Energie her.",
    "kcal": "Die Kilokalorie (kcal), im Allgemeinen auf Lebensmittelverpackungen als 'Kalorie' bezeichnet, entspricht 1.000 Kalorien oder 4.184 Joule, der Standardmaßeinheit zur Messung von Ernährungsenergie weltweit. Wenn Nährwertangaben '200 Kalorien' angeben, meinen sie 200 Kilokalorien, die die Energie darstellen, die Ihr Körper aus diesem Lebensmittel gewinnen kann. Eine Kilokalorie entspricht genau 4,184 Kilojoule, der Zahl, die auf Lebensmittelverpackungen in vielen Ländern verwendet wird.",
    "kwh": "Die Kilowattstunde (kWh) entspricht 3.600.000 Joule und ist die standardmäßige Abrechnungseinheit für den Stromverbrauch in Wohn- und Geschäftsräumen weltweit. Energieversorgungsunternehmen berechnen nach der Kilowattstunde, und das Verständnis dieser Einheit hilft Verbrauchern, die Betriebskosten von Geräten und die Leistung von Solarmodulen zu bewerten. Eine Kilowattstunde entspricht der Energie, die ein 1.000-Watt-Gerät in einer Stunde verbraucht.",
    "btu": "Die BTU (British Thermal Unit) entspricht ungefähr 1.055,06 Joule und wird definiert als die Wärmemenge, die benötigt wird, um ein Pfund Wasser um ein Grad Fahrenheit zu erwärmen. Sie ist die Haupteinheit zur Bewertung von Heiz- und Kühlausrüstung in den Vereinigten Staaten und erscheint auf Klimaanlagenspezifikationen, Ofenbewertungen und Energieeffizienzkennzeichnungen. Eine BTU entspricht etwa 0,2931 Wattstunden oder ungefähr 0,252 Kilokalorien.",
    "wh": "Die Wattstunde (Wh) entspricht 3.600 Joule und stellt die von einem ein Watt leistenden Gerät in einer Stunde verbrauchte Energie dar. Sie wird häufig für kleine Batteriekapazitäten, Ausgangsleistungen von Solarmodulen und Ladegrößen bei Elektrofahrzeugen verwendet, bei denen Kilowattstunden eine zu große Einheit wären. Eine Wattstunde entspricht genau 0,001 Kilowattstunden oder etwa 3,412 BTU."
  },
  "power": {
    "w": "Das Watt (W) ist die SI-Basiseinheit der Leistung, definiert als ein Joule pro Sekunde, und misst die Rate des Energieflusses. Von der Helligkeitsbewertung von Glühbirnen bis hin zur Ausgangsleistung von Telefonladegeräten taucht das Watt in den Produktspezifikationen weltweit im Alltag auf. Ein Watt entspricht genau 1 Joule pro Sekunde oder etwa 0,001341 PS.",
    "kw": "Das Kilowatt (kW) entspricht 1.000 Watt und ist die standardmäßige Einheit zur Messung der Leistungsabgabe von Motoren, Elektroheizungen und Industrieanlagen. Stromrechnungen verwenden Kilowattstunden (kW × Stunden), wodurch das Kilowatt die bekannteste Längeneinheit für Verbraucher ist. Ein Kilowatt entspricht ungefähr 1,341 Pferdestärken.",
    "mw": "Das Megawatt (MW) entspricht einer Million Watt und wird verwendet, um die Leistung von Kraftwerken, großen Industrieanlagen und Rechenzentren auszudrücken. Eine typische Windkraftanlage erzeugt 2–3 MW, während ein großes Kohlekraftwerk 500–1.000 MW produzieren kann. Ein Megawatt kann ungefähr 800–1.000 Haushalte gleichzeitig mit Strom versorgen.",
    "hp": "Pferdestärke (PS) ist eine imperiale Maßeinheit der Leistung, die ungefähr 745,7 Watt entspricht, ursprünglich von James Watt definiert, um die Leistung von Dampfmaschinen mit Zugpferden zu vergleichen. Sie bleibt die Standardmaßeinheit zur Bewertung von Auto- motoren, Rasenmähern und Bootsmotoren, insbesondere in den Vereinigten Staaten. Eine Pferdestärke entspricht etwa 0,7457 Kilowatt oder 1,0139 metrischer Pferdestärke.",
    "ps": "Die metrische Pferdestärke (PS, Pferdestärke) entspricht ungefähr 735,5 Watt, etwas weniger als die imperiale Pferdestärke, und ist die standardmäßige Leistungseinheit für Fahrzeugbewertungen in ganz Europa und Asien. Autospezifikationen in Deutschland, Japan und China geben typischerweise die Motorleistung in PS an. Eine PS entspricht etwa 0,9863 imperialen Pferdestärken oder 0,7355 Kilowatt.",
    "btuh": "BTU pro Stunde (BTU/h) entspricht ungefähr 0,293 Watt, der standardmäßigen Bewertungseinheit für Klimaanlagen, Heizgeräte und Öfen in Nordamerika. Eine typische Fensterklimaanlage mit einer Leistung von 10.000 BTU/h kann einen 400–500 Quadratfuß großen Raum kühlen, was diese Einheit für die Dimensionierung von HLK-Systemen unerlässlich macht. Ein BTU/h entspricht etwa 0,2931 Watt.",
    "ftlbs": "Fuß-Pfund pro Sekunde (ft·lbf/s) entspricht ungefähr 1,356 Watt, eine imperiale Leistungseinheit, die gelegentlich im Maschinenbau verwendet wird. Obwohl sie für Motorbewertungen weniger gebräuchlich ist als Pferdestärken, bietet sie eine direkte Verbindung zwischen Drehmoment und Drehzahl. Ein Fuß-Pfund pro Sekunde entspricht etwa 1,356 Watt oder 0,00182 Pferdestärken.",
    "calps": "Kalorien pro Sekunde (cal/s) entsprechen genau 4,184 Watt und werden hauptsächlich in der Thermodynamik und Physik verwendet, um Wärmetransferraten auszudrücken. Obwohl es keine gebräuchliche Alltagseinheit ist, verbindet sie thermische und mechanische Leistungsberechnungen in der wissenschaftlichen Forschung. Eine Kalorie pro Sekunde entspricht genau 4,184 Watt oder etwa 0,00561 Pferdestärken."
  },
  "fuel": {
    "kml": "Kilometer pro Liter (km/L) ist die standardmäßige Kraftstoffeffizienzmetrik, die in den meisten Ländern außerhalb der USA und Großbritanniens verwendet wird und misst, wie weit ein Fahrzeug mit einem Liter Kraftstoff fährt. Ein typisches Kompaktfahrzeug erreicht 12–18 km/L, während Hybride über 25 km/L erreichen können. Ein km/L entspricht ungefähr 2,352 Meilen pro US-Gallone.",
    "l100": "Liter pro 100 km (L/100km) ist die umgekehrte Kraftstoffeffizienzmetrik, die in Europa und Australien verwendet wird und misst, wie viele Liter Kraftstoff ein Fahrzeug über 100 Kilometer verbraucht. Niedrigere Zahlen bedeuten eine bessere Effizienz — ein Auto, das mit 5 L/100km bewertet ist, verbraucht weniger Kraftstoff als eines, das mit 8 L/100km bewertet ist. Dies ist das Inverse von km/L: L/100km = 100 / km/L.",
    "mpg_us": "Meilen pro US-Gallone (mpg) messen, wie viele Meilen ein Fahrzeug mit einer US-Gallone (3,785 Liter) Kraftstoff zurücklegen kann, das Standardeffizienzmaß in den Vereinigten Staaten. Die Kraftstoffverbrauchswerte der US-amerikanischen EPA zeigen Stadt- und Autobahn-mpg-Werte für jedes neue Fahrzeug an. Ein US-mpg entspricht ungefähr 0,425 km/L oder etwa 23,52 L/100 km.",
    "mpg_uk": "Meilen pro Gallone UK (imperiale mpg) misst die Entfernung pro imperiale Gallone (4,546 Liter), die im Vereinigten Königreich für Kraftstoffverbrauchsangaben verwendet wird. Da die imperiale Gallone größer als die US-Gallone ist, zeigt dasselbe Auto im britischen System eine höhere mpg-Zahl. Ein britisches mpg entspricht ungefähr 0,354 km/L oder etwa 28,25 L/100 km."
  },
  "frequency": {
    "hz": "Das Hertz (Hz) ist die SI-Basiseinheit der Frequenz, definiert als ein Zyklus pro Sekunde, und misst, wie oft ein sich wiederholendes Ereignis auftritt. Von der Frequenz des Wechselstromnetzes (50 oder 60 Hz) bis zu Audiosignalen und Prozessor-Taktgeschwindigkeiten ist Hertz die universelle Sprache der Frequenz. Ein Hertz entspricht genau einem Zyklus pro Sekunde.",
    "khz": "Das Kilohertz (kHz) entspricht 1.000 Hertz und wird häufig verwendet, um Audiofrequenzen, Rundfunkbänder und frühe Computerprozessor-Geschwindigkeiten zu beschreiben. Das menschliche Gehör reicht von etwa 20 Hz bis 20 kHz, wodurch diese Einheit in der Tontechnik und Musikproduktion wesentlich ist. Ein Kilohertz entspricht 1.000 Zyklen pro Sekunde.",
    "mhz": "Das Megahertz (MHz) entspricht einer Million Hertz und wird häufig für Funkfrequenzbänder, frühe CPU-Taktraten und drahtlose Kommunikationsstandards verwendet. UKW-Rundfunksendungen erfolgen im Bereich von 88–108 MHz, während frühe Personalcomputer nur mit wenigen MHz arbeiteten. Ein Megahertz entspricht 1.000.000 Zyklen pro Sekunde.",
    "ghz": "Das Gigahertz (GHz) entspricht einer Milliarde Hertz, der standardmäßigen Einheit für moderne CPU-Taktfrequenzen, Wi-Fi-Frequenzen und 5G-Mobilfunkbänder. Ein typischer Laptop-Prozessor arbeitet mit 2–5 GHz, während Wi-Fi mit 2,4 GHz oder 5 GHz betrieben wird. Ein Gigahertz entspricht 1.000 Megahertz oder einer Milliarde Zyklen pro Sekunde.",
    "rpm": "Umdrehungen pro Minute (rpm) messen die Rotationsgeschwindigkeit und geben an, wie viele vollständige Umdrehungen ein Objekt in einer Minute macht. Es ist die gebräuchlichste Einheit für Motordrehzahlen, Drehgeschwindigkeiten von Festplatten und Spezifikationen von Elektrowerkzeugen weltweit. Eine Umdrehung pro Minute entspricht genau 1/60 Hertz oder ungefähr 0,01667 Hz.",
    "rps": "Umdrehungen pro Sekunde (rps) messen die Rotationsgeschwindigkeit als vollständige Umdrehungen pro Sekunde, was genau einem Hertz entspricht. Obwohl im Alltag seltener als U/min verwendet, wird rps in der Physik, Ingenieuranalyse und bei einigen Industriemaschinenbewertungen eingesetzt. Eine rps entspricht genau 60 U/min."
  },
  "angle": {
    "deg": "Das Grad (°) ist die gebräuchlichste Einheit zur Messung von Winkeln und teilt einen vollständigen Kreis in 360 gleiche Teile. Von der Navigation und dem Bauwesen bis hin zur alltäglichen Geometrie sind Grad weltweit die standardmäßige Winkeleinheit. Ein Grad entspricht π/180 Radianten oder etwa 0,01745 Radianten.",
    "rad": "Das Radian (rad) ist die SI-Einheit der Winkelmessung, definiert als der durch einen Bogen eingeschlossene Winkel, dessen Länge gleich dem Radius des Kreises ist. Es ist die natürliche Einheit für trigonometrische Funktionen in Mathematik und Physik — sin, cos und tan setzen alle Radianteneingaben voraus. Ein Radian entspricht ungefähr 57,296 Grad.",
    "grad": "Der Gradian (gon), auch Grad genannt, teilt einen rechten Winkel in 100 gleiche Teile, sodass ein voller Kreis 400 Gradiane hat. Er wird hauptsächlich in der Vermessung und in einigen europäischen militärischen Kartierungssystemen verwendet, wobei das Basis-100-System die Dezimalberechnungen vereinfacht. Ein Gradian entspricht genau 0,9 Grad.",
    "arcmin": "Die Bogenminute (′) entspricht 1/60 eines Grades und wird in der Astronomie, Kartografie und präzisen Navigation verwendet, wo eine feine Winkelauflösung benötigt wird. Sterne werden nach ihren Koordinaten in Grad und Bogenminuten katalogisiert, und die Genauigkeit der Teleskopausrichtung wird oft in Bogenminuten angegeben. Eine Bogenminute entspricht 1/60 Grad oder etwa 0,000291 Radianten.",
    "arcsec": "Die Bogensekunde (″) entspricht 1/3600 eines Grades und bietet eine äußerst feine Winkelaulösung für Astronomie, Optik und Satellitenbilder. Das Hubble-Weltraumteleskop hat eine Auflösung von etwa 0,05 Bogensekunden, und Messungen der stellaren Parallaxe verwenden Präzision im Millibogensekundenbereich. Eine Bogensekunde entspricht 1/3600 Grad oder etwa 0,00000485 Radianten.",
    "turn": "Eine Umdrehung (tr), auch Revolution genannt, stellt eine vollständige Drehung von 360 Grad oder 2π Radianten dar. Sie wird in ingenieurtechnischen Zusammenhängen verwendet, die Rotationsmechanik, Spezifikationen von Elektromotoren und Berechnungen der Winkelgeschwindigkeit betreffen, wo ganze Drehungen intuitiver sind als Grad oder Radianten. Eine Umdrehung entspricht genau 360 Grad."
  },
  "force": {
    "n": "Das Newton (N) ist die SI-Basiseinheit der Kraft, definiert als die Kraft, die erforderlich ist, um ein Kilogramm Masse mit einem Meter pro Sekunde² zu beschleunigen. Benannt nach Isaac Newton, ist es die fundamentale Einheit in der Mechanik, im Bauingenieurwesen und in der Physik weltweit. Ein Newton entspricht ungefähr 0,2248 Pfund-Kraft.",
    "kn": "Der Kilonewton (kN) entspricht 1.000 Newton und wird im Bauingenieurwesen verwendet, um Gebäudelasten, Brückenkapazitäten und Materialstärken zu erklären. Ein typisches Pkw wiegt etwa 10–15 kN, und Bauvorschriften geben Entwurfsbelastungen in kN pro Quadratmeter an. Ein Kilonewton entspricht ungefähr 224,8 Pfundkraft.",
    "lbf": "Pfund-Kraft (lbf) ist die standardmäßige imperiale Maßeinheit der Kraft in den Vereinigten Staaten, definiert als die Gravitationskraft, die auf ein Pfund Masse auf Meereshöhe wirkt. Sie erscheint in Spannungswerten von Bolzen, Materialprüfungen und mechanischen Ingenieurspezifikationen in ganz Nordamerika. Ein Pfund-Kraft entspricht ungefähr 4,448 Newton.",
    "kgf": "Kilopond (kgf) ist eine Nicht-SI-Einheit, die als die Gravitationskraft auf ein Kilogramm Masse bei der Standardgravitation definiert ist und genau 9,80665 Newton entspricht. Sie wird häufig in einigen Ingenieurbereichen und in Ländern verwendet, die von metrischen technischen Einheiten auf das SI-System umstellen. Ein Kilogrammkraft entspricht ungefähr 2,205 Pfund-Kraft.",
    "dyn": "Die Dyne (dyn) ist eine Zentimeter-Gramm-Sekunde (CGS) Einheit der Kraft, die genau 0,00001 Newton entspricht und hauptsächlich in der Physik für Berechnungen kleiner Kräfte verwendet wird. Sie stellt die Kraft dar, die erforderlich ist, um ein Gramm Masse mit einem Zentimeter pro Sekunde zum Quadrat zu beschleunigen, und tritt in Messungen der Oberflächenspannung und der elektromagnetischen Kraft auf. Eine Dyne entspricht genau 10 Mikro-Newton.",
    "ozf": "Unzen-Kraft (ozf) entspricht ungefähr 0,278 Newton, der britischen Einheit für kleine Kraftmessungen in der Präzisionsingenieurtechnik, Federkalibrierung und mikro-mechanischen Prüfung. Sie ist besonders nützlich zum Messen von Abzugsgewichten, kleinen Federkräften und empfindlichen Instrumentenkalibrierungen. Eine Unzen-Kraft entspricht etwa 1/16 einer Pfund-Kraft."
  },
  "torque": {
    "nm": "Das Newton-Meter (N·m) ist die SI-Einheit des Drehmoments und misst die Drehkraft, die entsteht, wenn eine Kraft von einem Newton in einem Abstand von einem Meter vom Drehpunkt angewendet wird. Es ist die Standardeinheit für Angaben zum Motordrehmoment, Anforderungen zum Anziehen von Schrauben und mechanische Konstruktionen weltweit. Ein Newton-Meter entspricht ungefähr 0,7376 Fuß-Pfund.",
    "kNm": "Der Kilonewton-Meter (kN·m) entspricht 1.000 Newton-Metern und wird im Bau- und Tragwerksbau für großtechnische Drehmomentspezifikationen an Brücken, Kränen und schweren Industrieanlagen verwendet. Fundamentbolzenspezifikationen und Drehmomentangaben für Windkraftanlagen werden häufig in kN·m angegeben. Ein kN·m entspricht ungefähr 737,6 Fuß-Pfund.",
    "lbft": "Pfund-Fuß (lb·ft) ist die imperiale Einheit des Drehmoments, die hauptsächlich in den Vereinigten Staaten und im Vereinigten Königreich für Spezifikationen von Automobilmotoren und das Anziehen mechanischer Schraubverbindungen verwendet wird. Autofans diskutieren die Motorleistung in lb·ft, und Drehmomentschlüssel in den USA sind in dieser Einheit kalibriert. Ein Pfund-Fuß entspricht ungefähr 1,356 Newtonmetern.",
    "lbin": "Pfund-Zoll (lb·in) ist eine imperiale Drehmomenteinheit für kleinere präzise Anwendungen, die häufig für die Montage von Elektronik, Spezifikationen kleiner Motoren und Kalibrierung von Instrumenten verwendet wird. Drehmomentschraubendreher und Präzisionsbefestigungs-Spezifikationen in den USA verwenden typischerweise lb·in. Ein Pfund-Zoll entspricht ungefähr 0,113 Newtonmetern oder 1/12 eines Pfund-Fußes.",
    "kgfm": "Kilogramm-Kraftmeter (kgf·m) ist eine metrische technische Einheit des Drehmoments, die in Japan, China und anderen asiatischen Ländern häufig für Motor- und Maschinenspezifikationen verwendet wird. Obwohl sie kein Teil des SI-Systems ist, bleibt sie in den Automobilspezifikationen in ganz Ostasien Standard. Ein kgf·m entspricht ungefähr 9,807 Newtonmetern oder etwa 7,233 Fuß-Pfund.",
    "ozin": "Unzen-Zoll (oz·in) ist eine kleine imperiale Drehmomenteinheit, die für Präzisionsinstrumente, Uhrmacherei und mikromechanische Montagen verwendet wird, bei denen selbst Pfund-Zoll zu groß wären. Kleine Servomotoren, Kameralinsenmechanismen und empfindliche elektronische Befestigungen werden in oz·in angegeben. Eine Unzen-Zoll entspricht ungefähr 0,00706 Newtonmetern."
  },
  "shoe": {
    "cm": "Zentimeter (cm) stellen die tatsächliche Fußlängenmessung dar, den universellen Bezugspunkt für alle Schuhgrößen-Umrechnungssysteme. Das Messen Ihres Fußes in Zentimetern ist zunächst der zuverlässigste Weg, um Ihre korrekte Größe in den US-, UK-, EU- und japanischen Systemen zu finden, da jede Region unterschiedliche Nummerierungsskalen verwendet. Ein typischer Fuß eines erwachsenen Mannes misst 26–28 cm.",
    "us_m": "US-Herrenschuhgrößen folgen einer Skala, bei der Größe 9 einer Fußlänge von ungefähr 27 cm entspricht, wobei jede halbe Größe etwa 0,42 cm hinzufügt. Das US-System wird in ganz Nordamerika verwendet und unterscheidet sich von den UK-Größen um ungefähr eine volle Größe (US 9 ≈ UK 8). Sportschuhgrößen können je nach Marke leicht variieren.",
    "us_w": "US-Damenschuhgrößen sind ungefähr 1,5 Größen höher in der Zahl als US-Herrenschuhgrößen für dieselbe Fußlänge, wobei US-Damen 9 etwa 25,4 cm Fußlänge entspricht. Dieser Unterschied führt oft zu Verwirrung beim Kauf von Unisex- oder Sportschuhen. US-Damen 9 ≈ US-Herren 7,5 ≈ EU 40 ≈ UK 6,5.",
    "uk": "Die britischen Schuhgrößen bilden die Grundlage für das US-System, sind jedoch um ungefähr eine Größe verschoben – UK 8 entspricht einem US-Herrenschuh 9 und einer Fußlänge von etwa 27 cm. Das britische System wird in ganz Großbritannien, Irland und vielen Commonwealth-Ländern verwendet und stimmt eng mit dem indischen Schuhgrößensystem überein.",
    "eu": "EU-Schuhgrößen (auch als kontinentale oder Pariser Punktgrößen bezeichnet) verwenden eine Skala, bei der jede Größenzunahme 2/3 cm (6,67 mm) in der Fußlänge entspricht, wodurch EU 42 ungefähr 26,7 cm beträgt. Das EU-System wird in ganz Kontinentaleuropa verwendet und ist der gebräuchlichste internationale Standard. Die Umrechnung zwischen EU- und US-/UK-Größen erfordert die Kenntnis der Fußlänge.",
    "jp": "Japanische Schuhgrößen (auch in Korea verwendet) entsprechen direkt der Fußlänge in Millimetern — JP 260 bedeutet einen 26 cm langen Fuß, JP 270 bedeutet 27 cm. Dies macht das japanische System am einfachsten und intuitivsten, da die Größenangabe direkt der Fußmessung entspricht. Japanische Größen reichen typischerweise von 230 (Damen) bis 290 (Herren groß)."
  }
};
